# Adaptive rejection sampling following Gilks and Wild (1992).
# The density function must accept a numeric vector and return a vector
# of nonnegative (possibly unnormalised) density values.

sample_count <- 100

.ars_validate_domain <- function(domain) {
  if (!is.numeric(domain) || length(domain) != 2L || anyNA(domain))
    stop("domain must be a numeric vector of length two")
  if (domain[1] >= domain[2]) stop("domain must satisfy domain[1] < domain[2]")
  if (is.nan(domain[1]) || is.nan(domain[2])) stop("domain contains NaN")
  invisible(TRUE)
}

.ars_eval_log_density <- function(f, x, domain) {
  if (!is.numeric(x)) stop("internal error: x must be numeric")
  if (any(x < domain[1] | x > domain[2])) stop("point outside domain")
  z <- tryCatch(f(x), error = function(e) stop("density_function failed: ", e$message))
  if (!is.numeric(z) || length(z) != length(x))
    stop("density_function must return a numeric vector of the same length")
  if (any(is.na(z)) || any(!is.finite(z) & z != 0) || any(z < 0))
    stop("density_function must return finite nonnegative values")
  ans <- rep(-Inf, length(z))
  good <- z > 0
  ans[good] <- log(z[good])
  ans
}

.ars_initial_knots <- function(domain) {
  lo <- domain[1]; hi <- domain[2]
  if (is.finite(lo) && is.finite(hi)) {
    p <- seq(0.08, 0.92, length.out = 5)
    return(lo + p * (hi - lo))
  }
  if (!is.finite(lo) && !is.finite(hi)) return(c(-4, -1, 0, 1, 4))
  if (!is.finite(lo)) return(hi - c(8, 4, 2, 1, 0.25))
  return(lo + c(0.05, 0.25, 1, 3, 8))
}

.ars_derivative <- function(f, x, domain) {
  # A finite-difference derivative is adequate for the continuously
  # differentiable densities normally used with ARS.
  h <- 1e-5 * max(1, abs(x))
  a <- if (is.finite(domain[1])) max(domain[1], x - h) else x - h
  b <- if (is.finite(domain[2])) min(domain[2], x + h) else x + h
  if (b <= a) stop("cannot calculate a derivative at this domain")
  ya <- .ars_eval_log_density(f, a, domain)
  yb <- .ars_eval_log_density(f, b, domain)
  if (!is.finite(ya) || !is.finite(yb)) stop("density is zero near an initial knot")
  (yb - ya) / (b - a)
}

.ars_check_concavity <- function(x, y, d, tolerance = 2e-3) {
  keep <- is.finite(y) & is.finite(d)
  if (sum(keep) < 3) stop("density has insufficient positive support for ARS")
  xx <- x[keep]; dd <- d[keep]
  if (any(diff(dd) > tolerance * (1 + abs(dd[-length(dd)]))))
    stop("density appears not to be log-concave")
  if (length(xx) >= 3) {
    slopes <- diff(y[keep]) / diff(xx)
    if (any(diff(slopes) > 5e-3 * (1 + abs(slopes[-length(slopes)]))))
      stop("density appears not to be log-concave")
  }
  invisible(TRUE)
}

.ars_hull <- function(x, y, d, domain) {
  m <- length(x)
  z <- numeric(m + 1L)
  z[1] <- domain[1]
  z[m + 1L] <- domain[2]
  if (m > 1L) {
    for (i in 1:(m - 1L)) {
      den <- d[i] - d[i + 1L]
      if (abs(den) < 1e-12) z[i + 1L] <- (x[i] + x[i + 1L]) / 2
      else z[i + 1L] <- (y[i + 1L] - d[i + 1L] * x[i + 1L] -
                           y[i] + d[i] * x[i]) / den
    }
  }
  z[-1L] <- pmax(z[-1L], z[-length(z)] + 1e-12)
  z[1] <- domain[1]; z[m + 1L] <- domain[2]
  if (any(z[-1L] <= z[-length(z)])) stop("failed to construct ARS hull")
  list(bounds = z, slopes = d, intercepts = y - d * x)
}

.ars_interval_mass <- function(a, b, slope, intercept) {
  # Integral of exp(intercept + slope*x), with stable handling of slope zero.
  if (is.infinite(a) || is.infinite(b)) {
    if ((is.infinite(a) && slope <= 0) || (is.infinite(b) && slope >= 0))
      return(Inf)
  }
  if (abs(slope) < 1e-10) return(exp(intercept) * (b - a))
  v <- exp(intercept + slope * a) * (-expm1(slope * (b - a))) / slope
  if (!is.finite(v) || v <= 0) {
    # Equivalent expression for large exponents.
    v <- (exp(intercept + slope * b) - exp(intercept + slope * a)) / slope
  }
  v
}

.ars_draw_from_interval <- function(a, b, slope, intercept, u) {
  if (abs(slope) < 1e-10) return(a + u * (b - a))
  # Invert the truncated exponential using the endpoint with the smaller
  # exponent to avoid overflow.
  if (slope > 0) {
    eb <- exp(slope * (b - a))
    a + log1p(u * (eb - 1)) / slope
  } else {
    a + log1p(-u * (1 - exp(slope * (b - a)))) / slope
  }
}

ars <- function(density_function, domain, n = sample_count) {
  if (!is.function(density_function)) stop("density_function must be a function")
  .ars_validate_domain(domain)
  if (length(n) != 1L || !is.numeric(n) || is.na(n) || !is.finite(n) || n < 0 || n != as.integer(n))
    stop("n must be one nonnegative finite integer")
  n <- as.integer(n)
  if (n == 0L) return(numeric(0))

  knots <- sort(unique(.ars_initial_knots(domain)))
  knots <- knots[knots > domain[1] & knots < domain[2]]
  y <- .ars_eval_log_density(density_function, knots, domain)
  if (any(!is.finite(y))) stop("density must be positive at initial knots")
  d <- vapply(knots, function(q) .ars_derivative(density_function, q, domain), numeric(1))
  .ars_check_concavity(knots, y, d)

  ans <- numeric(n); got <- 0L; iterations <- 0L
  while (got < n) {
    iterations <- iterations + 1L
    if (iterations > 100000L) stop("ARS exceeded iteration limit; check the density")
    ord <- order(knots); knots <- knots[ord]; y <- y[ord]; d <- d[ord]
    hull <- .ars_hull(knots, y, d, domain)
    masses <- vapply(seq_along(d), function(i)
      .ars_interval_mass(hull$bounds[i], hull$bounds[i + 1L], d[i], hull$intercepts[i]), numeric(1))
    if (any(!is.finite(masses)) || sum(masses) <= 0 || !is.finite(sum(masses)))
      stop("invalid or nonintegrable ARS envelope")
    k <- sample.int(length(masses), 1L, prob = masses)
    x <- .ars_draw_from_interval(hull$bounds[k], hull$bounds[k + 1L], d[k], hull$intercepts[k], runif(1))
    lx <- .ars_eval_log_density(density_function, x, domain)
    ux <- hull$intercepts[k] + hull$slopes[k] * x
    if (!is.finite(lx) || lx > ux + 1e-7) stop("density violates log-concavity or ARS envelope")
    if (log(runif(1)) <= lx - ux) {
      got <- got + 1L; ans[got] <- x
    } else {
      # Rejection points refine the upper hull.
      dy <- .ars_derivative(density_function, x, domain)
      knots <- c(knots, x); y <- c(y, lx); d <- c(d, dy)
      .ars_check_concavity(knots[order(knots)], y[order(knots)], d[order(knots)])
    }
  }
  ans
}

.test_line <- function(name, ok, x) {
  cat(sprintf("%s: %s (mean=%.4f, sd=%.4f)\n", name, if (ok) "PASS" else "FAIL", mean(x), sd(x)))
  invisible(ok)
}

test <- function() {
  set.seed(2024)
  z <- ars(function(x) dnorm(x), c(-Inf, Inf), 3000)
  ok1 <- abs(mean(z)) < 0.12 && abs(sd(z) - 1) < 0.12
  .test_line("NORMAL_SAMPLING", ok1, z)
  write.table(z, "/app/normal_samples.txt", row.names = FALSE, col.names = FALSE)

  e <- ars(function(x) dexp(x), c(0, Inf), 3000)
  ok2 <- abs(mean(e) - 1) < 0.12 && abs(sd(e) - 1) < 0.12 && all(e >= 0)
  .test_line("EXPONENTIAL_SAMPLING", ok2, e)
  write.table(e, "/app/exponential_samples.txt", row.names = FALSE, col.names = FALSE)

  bad <- tryCatch({ ars(function(x) exp(-(x^2 - 1)^2), c(-3, 3), 10); FALSE }, error = function(e) TRUE)
  cat(sprintf("NON_LOG_CONCAVE_REJECTION: %s (mean=NA, sd=NA)\n", if (bad) "PASS" else "FAIL"))
  invalid <- tryCatch({ ars(dnorm, c(1, 0), 2); FALSE }, error = function(e) TRUE)
  cat(sprintf("INPUT_VALIDATION: %s (mean=NA, sd=NA)\n", if (invalid) "PASS" else "FAIL"))
  all(c(ok1, ok2, bad, invalid))
}
EOF
Rscript -e 'source("/app/ars.R"); ok <- test(); if (!isTRUE(ok)) quit(status=1)'
ls -lh /app/ars.R /app/normal_samples.txt /app/exponential_samples.txt

