# Adaptive rejection sampler (Gilks, Wild & Gilks, 1992).
# density_function must be vectorized and return nonnegative values.

.ars_logf <- function(f, x, domain) {
  if (any(x < domain[1] | x > domain[2])) stop("evaluation outside domain")
  v <- tryCatch(f(x), error=function(e) stop("density_function error: ", e$message))
  if (!is.numeric(v) || length(v) != length(x) || anyNA(v) || any(v < 0) || any(is.nan(v)))
    stop("density_function must return a nonnegative numeric vector of matching length")
  z <- rep(-Inf, length(v)); ii <- v > 0 & is.finite(v); z[ii] <- log(v[ii]); z
}

.ars_knots <- function(domain) {
  a <- domain[1]; b <- domain[2]
  if (is.finite(a) && is.finite(b)) return(a + (b-a)*c(.08,.25,.50,.75,.92))
  if (!is.finite(a) && !is.finite(b)) return(c(-4,-1,0,1,4))
  if (!is.finite(a)) return(b-c(8,4,2,1,.25))
  a+c(.05,.25,1,3,8)
}

.ars_slope <- function(f, x, domain) {
  h <- 1e-5*max(1,abs(x)); left <- max(domain[1],x-h); right <- min(domain[2],x+h)
  if (right <= left) stop("cannot calculate numerical derivative")
  yl <- .ars_logf(f,left,domain); yr <- .ars_logf(f,right,domain)
  if (!is.finite(yl) || !is.finite(yr)) stop("density must be positive near every knot")
  (yr-yl)/(right-left)
}

.ars_concave <- function(x,y,s) {
  if (length(x)<3 || any(!is.finite(y)) || any(!is.finite(s))) stop("density has inadequate positive support")
  # Derivatives of a concave log density are nonincreasing.
  if (any(diff(s) > .01*(1+abs(s[-length(s)])))) stop("density appears not to be log-concave")
  q <- diff(y)/diff(x)
  if (length(q)>1 && any(diff(q) > .02*(1+abs(q[-length(q)])))) stop("density appears not to be log-concave")
  TRUE
}

.ars_hull <- function(x,y,s,domain) {
  m <- length(x); z <- c(domain[1],rep(NA_real_,m-1),domain[2])
  for (i in seq_len(m-1)) {
    den <- s[i]-s[i+1]
    z[i+1] <- if (abs(den)<1e-12) (x[i]+x[i+1])/2 else
      (y[i+1]-s[i+1]*x[i+1]-y[i]+s[i]*x[i])/den
  }
  z <- cummax(z); z[1] <- domain[1]; z[m+1] <- domain[2]
  if (any(diff(z)<=0)) stop("failed to construct ARS hull")
  list(z=z, slope=s, intercept=y-s*x)
}

.ars_logmass <- function(a,b,s,c) {
  if (is.infinite(a) && s <= 0) return(-Inf)
  if (is.infinite(b) && s >= 0) return(-Inf)
  if (abs(s)<1e-9) return(c+log(b-a))
  # factor at the finite/lower endpoint; this is stable for normal tails.
  if (is.finite(a)) return(c+s*a+log(abs(expm1(s*(b-a))))-log(abs(s)))
  c+s*b+log(abs(expm1(s*(a-b))))-log(abs(s))
}

.ars_draw <- function(a,b,s,u) {
  if (abs(s)<1e-9) return(a+u*(b-a))
  if (is.finite(a)) {
    if (is.infinite(b)) return(a-log1p(-u)/s)
    d <- s*(b-a)
    if (s>0) return(a+log1p(u*expm1(d))/s)
    return(a+log1p(-u*(1-exp(d)))/s)
  }
  # only possible for a=-Inf and s>0; use distance from b
  b+log(u)/s
}

ars <- function(density_function, domain, n=sample_count) {
  if (!is.function(density_function)) stop("density_function must be a function")
  if (!is.numeric(domain) || length(domain)!=2 || anyNA(domain) || domain[1]>=domain[2])
    stop("domain must be numeric length two with lower < upper")
  if (length(n)!=1 || !is.numeric(n) || !is.finite(n) || n<0 || n!=as.integer(n))
    stop("n must be a nonnegative integer")
  n <- as.integer(n); if (!n) return(numeric())
  x <- sort(unique(.ars_knots(domain))); y <- .ars_logf(density_function,x,domain)
  s <- vapply(x,function(q) .ars_slope(density_function,q,domain),numeric(1))
  .ars_concave(x,y,s)
  out <- numeric(n); got <- 0L; iter <- 0L
  while (got<n) {
    iter <- iter+1L; if (iter>200000) stop("ARS iteration limit exceeded")
    o <- order(x); x<-x[o]; y<-y[o]; s<-s[o]; h <- .ars_hull(x,y,s,domain)
    lm <- vapply(seq_along(s),function(i) .ars_logmass(h$z[i],h$z[i+1],s[i],h$intercept[i]),numeric(1))
    if (all(!is.finite(lm))) stop("density has no usable integrable envelope")
    mx <- max(lm); pr <- exp(lm-mx); pr[!is.finite(pr)] <- 0; k <- sample.int(length(pr),1,prob=pr)
    q <- .ars_draw(h$z[k],h$z[k+1],s[k],runif(1)); lq <- .ars_logf(density_function,q,domain)
    uq <- h$intercept[k]+s[k]*q
    if (!is.finite(lq) || lq>uq+1e-6) stop("density violates the ARS upper hull; not log-concave")
    if (log(runif(1)) <= lq-uq) { got<-got+1L; out[got]<-q }
    else { x<-c(x,q); y<-c(y,lq); s<-c(s,.ars_slope(density_function,q,domain)); .ars_concave(sort(x),y[order(x)],s[order(x)]) }
  }
  out
}

sample_count <- 100

.test_result <- function(name,ok,z) cat(sprintf("%s: %s (mean=%.4f, sd=%.4f)\n",name,if(ok)"PASS" else "FAIL",mean(z),sd(z)))

test <- function() {
  set.seed(12345)
  z <- ars(function(x) dnorm(x),c(-Inf,Inf),3000)
  ok1 <- abs(mean(z))<.12 && abs(sd(z)-1)<.12; .test_result("NORMAL_SAMPLING",ok1,z)
  write.table(z,"/app/normal_samples.txt",row.names=FALSE,col.names=FALSE)
  e <- ars(function(x) dexp(x),c(0,Inf),3000)
  ok2 <- abs(mean(e)-1)<.12 && abs(sd(e)-1)<.12 && all(e>=0); .test_result("EXPONENTIAL_SAMPLING",ok2,e)
  write.table(e,"/app/exponential_samples.txt",row.names=FALSE,col.names=FALSE)
  bad <- tryCatch({ars(function(x) exp(-(x^2-1)^2),c(-3,3),10);FALSE},error=function(e)TRUE)
  cat(sprintf("NON_LOG_CONCAVE_REJECTION: %s (mean=NA, sd=NA)\n",if(bad)"PASS" else "FAIL"))
  inv <- tryCatch({ars(dnorm,c(1,0),1);FALSE},error=function(e)TRUE)
  cat(sprintf("INPUT_VALIDATION: %s (mean=NA, sd=NA)\n",if(inv)"PASS" else "FAIL"))
  isTRUE(all(c(ok1,ok2,bad,inv)))
}
EOF
Rscript -e 'source("/app/ars.R"); ok<-test(); cat("ALL_TESTS:",if(ok)"PASS" else "FAIL","\n"); if(!ok) quit(status=1)'
